-- 1. 哈利法塔
(2, 1, '哈利法塔', 'Burj Khalifa', 'OTHER', '["地标","观景台","网红打卡","必去"]', '迪拜', '1 Sheikh Mohammed bin Rashid Blvd, Downtown Dubai', 25.1972, 55.2742, '每日 10:00-24:00（周末场次提前，以官网预约为准）', '2-3小时', '观景台门票约 149~378 迪拉姆（按楼层/时段分档）', '世界最高建筑（828米），124/125层及148层SKY观景台可俯瞰迪拜全城与棕榈岛，傍晚场可同时收获日景与夜景。', 1, 'ACTIVE'),
-- 2. 迪拜喷泉
(2, 1, '迪拜喷泉', 'The Dubai Fountain', 'OTHER', '["免费","夜景","表演"]', '迪拜', 'Downtown Dubai, Burj Lake', 25.1986, 55.2730, '表演每日约 18:00-23:00，每 30 分钟一场', '0.5-1小时', '湖畔观看免费；游船观赏约 65~110 迪拉姆', '全球最大音乐喷泉，位于哈利法塔下人工湖，水柱最高可达150米，配合灯光与音乐表演，是迪拜夜游经典项目。', 2, 'ACTIVE'),
-- 3. 迪拜购物中心
(2, 1, '迪拜购物中心', 'The Dubai Mall', 'SHOPPING', '["购物","水族馆","亲子","一站式"]', '迪拜', 'Financial Centre Rd, Downtown Dubai', 25.1969, 55.2792, '周六-周二 10:00-24:00，周三-周五至次日 01:00', '3-4小时', '商场免费进入；水族馆/观景台/溜冰场另收费', '全球体量最大的购物中心之一，2400余家店铺，内置迪拜水族馆、奥运标准溜冰场，并与哈利法塔和喷泉相连。', 3, 'ACTIVE'),
-- 4. 帆船酒店
(2, 1, '卓美亚帆船酒店', 'Burj Al Arab Jumeirah', 'OTHER', '["地标","奢华","拍照打卡"]', '迪拜', 'Jumeirah St, Burj Al Arab Area', 25.1198, 55.1503, '外部参观/餐饮需预约；非住客无法自由进入', '1-2小时', '下午茶或餐厅消费入门（人均约 300~750 迪拉姆）', '阿拉伯塔式帆船造型七星级（官方为豪华五星）酒店，建在人工岛上，是迪拜最具辨识度的奢华地标。', 4, 'ACTIVE'),
-- 5. 棕榈岛
(2, 1, '朱美拉棕榈岛', 'Palm Jumeirah', 'OTHER', '["人工岛","度假","拍照打卡"]', '迪拜', 'Palm Jumeirah, Dubai', 25.1136, 55.1340, '全天开放（单轨列车约 08:00-22:00）', '2-4小时', '岛上午餐免费；单轨列车约 20~40 迪拉姆', '世界著名人工群岛，形似棕榈树，云集亚特兰蒂斯、One&Only 等度假酒店，可乘单轨列车或登观景台俯瞰全岛。', 5, 'ACTIVE'),
-- 6. 棕榈岛观景台
(2, 1, '棕榈塔观景台 The View', 'The View at The Palm', 'OTHER', '["观景台","网红打卡","日落"]', '迪拜', 'Palm Tower, 52nd Floor, Palm Jumeirah', 25.1330, 55.1380, '每日 09:00-21:00（最后入场 20:30）', '1-1.5小时', '约 98~154 迪拉姆（成人/长者分档）', '位于棕榈塔52层的360度观景台，是俯瞰整个棕榈岛"树形"轮廓的最佳位置，日落时段最受欢迎。', 6, 'ACTIVE'),
-- 7. 亚特兰蒂斯水世界乐园
(2, 1, '亚特兰蒂斯水上乐园', 'Aquaventure Waterpark', 'THEME_PARK', '["亲子","刺激","水上乐园"]', '迪拜', 'Atlantis, The Palm Jumeirah', 25.1292, 55.1250, '每日 09:00-18:00（旺季延时）', '半天-1天', '日票约 289 迪拉姆起（常有促销）', '中东最大水上乐园之一，拥有吉尼斯认证的超长滑道"利维坦之牙"，可与鲨鱼共游隧道，亲子与刺激项目兼备。', 7, 'ACTIVE'),
-- 8. 迷失空间水族馆
(2, 1, '迷失空间水族馆', 'The Lost Chambers Aquarium', 'MUSEUM', '["亲子","海洋","亚特兰蒂斯"]', '迪拜', 'Atlantis, The Palm Jumeirah', 25.1290, 55.1245, '每日 10:00-21:00（最后入场 20:00）', '1.5-2小时', '约 135~225 迪拉姆（含互动项目另计）', '以亚特兰蒂斯古城为灵感设计的水族馆，65,000余只海洋生物生活在仿古遗迹般的水道中，含鲨鱼喂食秀。', 8, 'ACTIVE'),
-- 9. 未来博物馆
(2, 1, '未来博物馆', 'Museum of the Future', 'MUSEUM', '["科技感","网红建筑","沉浸式展览"]', '迪拜', 'Sheikh Zayed Rd, Trade Centre, Dubai', 25.2134, 55.2805, '每日 09:30-18:00（周二延时至 20:00，周一闭馆）', '2-3小时', '约 145 迪拉姆起，需提前官网购票', '外观为刻有阿拉伯文书法椭圆造型的"世界上最美建筑"之一，内部沉浸式展现2071年人类与科技的未来图景。', 9, 'ACTIVE'),
-- 10. 迪拜之框
(2, 1, '迪拜之框', 'Dubai Frame', 'MUSEUM', '["地标","观景","新旧迪拜对比"]', '迪拜', 'Zabeel Park, Khorfaka Rd, Al Kifaf', 25.2711, 55.3256, '每日 09:00-21:00（最后入场 20:15）', '1.5-2小时', '成人约 35~50 迪拉姆', '高150米的金色巨型画框，顶部悬空观景桥一侧可俯瞰老城迪拜河，另一侧尽览新城区摩天楼群。', 10, 'ACTIVE'),
-- 11. 奇迹花园
(2, 1, '迪拜奇迹花园', 'Dubai Miracle Garden', 'NATURE', '["花海","季节限定","亲子","拍照打卡"]', '迪拜', 'Barsha Heights (Dubai Al Barsha), near HPP Rounding', 25.0811, 55.0906, '旺季(约11月-次年4月) 日 09:00-21:00，周末至 23:00；夏季闭园', '2-3小时', '约 75~95 迪拉姆', '沙漠中的全球最大自然花圃，超1.5亿株花卉拼出城堡、飞机、米字旗等巨型造型，仅在凉爽季开放。', 11, 'ACTIVE'),
-- 12. 地球村
(2, 1, '迪拜地球村', 'Global Village', 'THEME_PARK', '["各国文化","夜市","表演","季节限定"]', '迪拜', 'Sheikh Mohammed bin Zayed Rd (E311), Dubai', 25.1780, 55.2850, '旺季(约10月-次年4月) 周日-周三 16:00-24:00，周四-周六至次日 01:00', '3-4小时', '门票约 25~40 迪拉姆（常有优惠）', '大型多元文化主题乐园，各国展馆、美食街、购物市集与 nightly 演出/烟花，冬季夜游热门目的地。', 12, 'ACTIVE'),
-- 13. 迪拜老城文化区
(2, 1, '阿尔法迪历史街区', 'Al Fahidi Historical Neighbourhood', 'HISTORY', '["老城","文艺","wind-tower风塔","免费"]', '迪拜', 'Al Fahidi Fort, Bur Dubai', 25.2636, 55.2966, '街区全天开放；展馆约 08:00-20:30', '1.5-2.5小时', '街区免费；部分展馆约 5~10 迪拉姆', '迪拜现存最古老街区之一，传统风塔土屋、艺术画廊与咖啡馆密布，是感受老迪拜风貌的必到之处。', 13, 'ACTIVE'),
